// Opaque internal user IDs (spec 005, research.md R1, FR-004/FR-012).
// Generated by the app at first sign-in; never derived from the email.
// Pure module — no env access, no I/O. Server-relevant but import-safe
// for tests (no "server-only": nothing secret here).
import { randomBytes } from "node:crypto";

/**
 * Generates a new internal user ID: 128 bits of cryptographic entropy,
 * base64url-encoded -> 22 characters (URL/Redis/cookie-safe).
 * Non-enumerable, non-decodable, stable once stored in the user record.
 */
export function generateUserId(): string {
  return randomBytes(16).toString("base64url");
}

const UID_SHAPE = /^[A-Za-z0-9_-]{1,64}$/;

/**
 * Shape check for uids arriving in session payloads. Accepts up to 64
 * base64url chars for forward compatibility (data-model.md "Session");
 * legacy `{ alias }` payloads fail this check because they have no uid.
 */
export function isUserIdShape(value: unknown): value is string {
  return typeof value === "string" && value.length >= 1 && UID_SHAPE.test(value);
}
